import React, { useEffect, useState } from "react";
import axios from "axios";
import { Link, useNavigate } from "react-router-dom";

interface Delivery {
  _id: string;
  customerId: string;
  driverId: string;
  status: string;
  location: {
    lat: number;
    lng: number;
  };
}

export default function DeliveryList() {
  const [deliveries, setDeliveries] = useState<Delivery[]>([]);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/delivery")
      .then((res) => {
        setDeliveries(res.data);
      })
      .catch((err) => {
        console.error("❌ Failed to fetch deliveries:", err);
        setError("API call failed. Check your backend.");
      });
  }, []);

  const handleDelete = async (id: string) => {
    if (window.confirm("Are you sure you want to delete this delivery?")) {
      try {
        await axios.delete(`http://localhost:5000/api/deliveries/${id}`);
        setDeliveries((prev) => prev.filter((d) => d._id !== id));
      } catch (error) {
        alert("❌ Failed to delete delivery");
        console.error(error);
      }
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Delivery List</h2>

      <button
        onClick={() => navigate("/")}
        style={{
          marginBottom: "20px",
          padding: "10px 20px",
          backgroundColor: "#6c757d",
          color: "#fff",
          border: "none",
          borderRadius: "4px",
          cursor: "pointer"
        }}
      >
        ← Back to Dashboard
      </button>

      {error && <p style={{ color: "red" }}>{error}</p>}

      {deliveries.length === 0 ? (
        <p>No deliveries available.</p>
      ) : (
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            marginTop: "10px"
          }}
        >
          <thead>
            <tr>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>
                Customer
              </th>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>
                Driver ID
              </th>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>
                Status
              </th>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>
                Location
              </th>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>
                Actions
              </th>
            </tr>
          </thead>
          <tbody>
            {deliveries.map((delivery) => (
              <tr key={delivery._id}>
                <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                  {delivery.customerId}
                </td>
                <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                  {delivery.driverId}
                </td>
                <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                  {delivery.status}
                </td>
                <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                  ({delivery.location.lat}, {delivery.location.lng})
                </td>
                <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                  <Link to={`/delivery/${delivery._id}`}>
                    <button style={{ marginRight: "10px" }}>📝 Edit</button>
                  </Link>
                  <button
                    onClick={() => handleDelete(delivery._id)}
                    style={{ backgroundColor: "red", color: "white" }}
                  >
                    🗑 Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
